--
-- Estructura de tabla para la tabla `system_files`
--

CREATE TABLE `system_files` (
  `id` int(10) UNSIGNED NOT NULL,
  `disk_name` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci NOT NULL,
  `file_name` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci NOT NULL,
  `file_size` int(11) NOT NULL,
  `content_type` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci NOT NULL,
  `title` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8 COLLATE utf8_spanish_ci DEFAULT NULL,
  `field` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci DEFAULT NULL,
  `attachment_id` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci DEFAULT NULL,
  `attachment_type` varchar(191) CHARACTER SET utf8 COLLATE utf8_spanish_ci DEFAULT NULL,
  `is_public` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_spanish2_ci;

